// calculator.js — a small math module.
// Every function here runs for real when you press Run.

function add(a, b) {
  return a + b;
}

function subtract(a, b) {
  return a - b;
}

function multiply(a, b) {
  return a * b;
}

function divide(a, b) {
  if (b === 0) {
    throw new Error('Cannot divide by zero');
  }
  return a / b;
}

module.exports = { add, subtract, multiply, divide };

function percent(part, whole) {
  return divide(part, whole) * 100;
}
module.exports.percent = percent;

function percent(part, whole) {
  return divide(part, whole) * 100;
}
module.exports.percent = percent;

function percentChange(from, to) {
  return percent(to - from, from);
}
module.exports.percentChange = percentChange;

